package ics.recents;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

import java.util.HashMap;

/** Holo_Lock (AOSP KitKat GlowPad) bitmaps, xhdpi (216px targets/handle, 16px dot). */
public class GlowArt {
    static final HashMap<String, Bitmap> cache = new HashMap<String, Bitmap>();

    static synchronized Bitmap get(String key) {
        Bitmap b = cache.get(key);
        if (b == null) {
            String s = data(key);
            byte[] raw = Base64.decode(s, Base64.DEFAULT);
            b = BitmapFactory.decodeByteArray(raw, 0, raw.length);
            cache.put(key, b);
        }
        return b;
    }

    static final String D_HANDLE = "";
    static final String D_UNLOCK = "";
    static final String D_UNLOCK_A = "";
    static final String D_CAMERA = "";
    static final String D_CAMERA_A = "";
    static final String D_ASSIST = "";
    static final String D_ASSIST_A = "";
    static final String D_DOT = "";

    static String data(String k) {
        if (k.equals("handle")) return D_HANDLE;
        if (k.equals("unlock")) return D_UNLOCK;
        if (k.equals("unlock_a")) return D_UNLOCK_A;
        if (k.equals("camera")) return D_CAMERA;
        if (k.equals("camera_a")) return D_CAMERA_A;
        if (k.equals("assist")) return D_ASSIST;
        if (k.equals("assist_a")) return D_ASSIST_A;
        if (k.equals("dot")) return D_DOT;
        throw new IllegalArgumentException(k);
    }
}
